@Service
public class OrderService implements OrderFacade {

    private static final ZoneId BUSINESS_ZONE = ZoneId.of("Europe/Warsaw");
    private static final int EXPIRY_DAYS = 30;

    private final OrderRepository orders;
    private final Clock clock;

    public OrderService(OrderRepository orders, Clock clock) {
        this.orders = orders;
        this.clock = clock;
    }

    @Override
    @Transactional
    public int expireStale() {
        LocalDate today = LocalDate.now(clock.withZone(BUSINESS_ZONE));
        LocalDate cutoff = today.minusDays(EXPIRY_DAYS);
        int cancelled = 0;
        for (Order order : orders.all()) {
            LocalDate placedOn = order.placedAt().atZone(BUSINESS_ZONE).toLocalDate();
            if ("PLACED".equals(order.status()) && placedOn.isBefore(cutoff)) {
                order.changeStatus("CANCELLED");
                cancelled++;
            }
        }
        return cancelled;
    }}

