import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    // 2026-06-30 12:00 Warsaw (CEST, UTC+2) is 10:00 UTC
    private static final Clock NOW = Clock.fixed(Instant.parse("2026-06-30T10:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, NOW);

    @Test
    void cancelsPlacedOrdersOlderThan30Days() {
        // 2026-05-30 is 31 days before 2026-06-30 in Warsaw
        Order old = place("2026-05-30T10:00:00Z");
        // 2026-05-31 is exactly 30 days before: not more than 30 days
        Order exactly30 = place("2026-05-31T10:00:00Z");

        assertEquals(1, service.expireStale());

        assertEquals("CANCELLED", old.status());
        assertEquals("PLACED", exactly30.status());
    }

    @Test
    void leavesOtherStatusesAlone() {
        Order confirmed = place("2026-01-01T10:00:00Z");
        confirmed.changeStatus("CONFIRMED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", confirmed.status());
    }

    @Test
    void usesTheWarsawCalendarDay() {
        // 2026-05-31 23:30 Warsaw is 21:30 UTC on 2026-05-31: still 30 days ago, not 31
        Order lateEvening = place("2026-05-31T21:30:00Z");
        // 2026-05-30 00:30 Warsaw is 2026-05-29 22:30 UTC: 31 days ago in Warsaw
        Order earlyMorning = place("2026-05-29T22:30:00Z");

        assertEquals(1, service.expireStale());

        assertEquals("PLACED", lateEvening.status());
        assertEquals("CANCELLED", earlyMorning.status());
    }

    @Test
    void secondRunCancelsNothingMore() {
        place("2026-01-01T10:00:00Z");

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private Order place(String placedAt) {
        String id = java.util.UUID.randomUUID().toString();
        Order order = new Order(id, "c-1", Money.pln(1000), Instant.parse(placedAt));
        orders.save(order);
        return order;
    }
}
}
